steps.script:
$o=@()
foreach($n in @('titulares.log','tendencias.log','ttittulares-mobile-trigger.log','ttendencias-mobile-trigger.log')){
 $p=Join-Path 'C:\TTiTTulares' $n
 if(-not(Test-Path $p)){continue}
 $tail=@(Get-Content $p -Tail 90 -ErrorAction SilentlyContinue)
 $hits=@($tail|Where-Object{$_ -match 'TT_GUARD|TOO_MANY_TABS|EDITORIAL RETRY DEFERRED|EDITORIAL_TAB_SOFT_PRESSURE|PREFLIGHT pages|MENSAJE ENVIADO|TRANSMISSION_UNVERIFIED' }|Select-Object -Last 4|ForEach-Object{
   $v=([string]$_ -replace 'https?://\S+','[URL]' -replace '[a-zA-Z0-9+/]{40,}={0,2}','[DATA]')
   $v.Substring(0,[Math]::Min(145,$v.Length))
 })
 $o+=@{file=$n;last=$hits}
}
Write-Output ('TTRESULT:'+(@{logs=$o}|ConvertTo-Json -Compress -Depth 4))
